/** Error response body. Served as ``application/problem+json``. */
export interface Problem {
  /** Problem type URI. */
  type?: string;
  /** Message rendered in the caller's locale. */
  title: string;
  /** HTTP status code. */
  status: number;
  /** Stable machine-readable error code and i18n key. */
  code: string;
  /** Typed values the client may use to render its own message. */
  params?: Record<string, unknown>;
  /** Correlates this response with server logs. */
  request_id?: string | null;
  /** Per-field detail for validation failures. */
  errors?: Array<FieldError> | null;
}

